var c=new LabPttController();
c.Press(0);
Console.WriteLine($"{c.Ptt}/{c.AudioOpen}"); // True/False
c.Frame(160,10);
Console.WriteLine($"{c.SentSamples}/{c.DroppedSamples}"); // 0/160
c.Ready(c.Epoch,60);
c.Frame(160,80);
Console.WriteLine($"{c.SentSamples}/{c.DroppedSamples}"); // 160/160

var c=new LabPttController { RequireGrant=true };
c.Press(0); int e=c.Epoch;
c.Ready(e,10); Console.WriteLine(c.State); // WaitingGrant
c.Grant(e,20); Console.WriteLine(c.State); // Keying
Console.WriteLine(c.AudioOpen); // False
c.Ready(e,40); Console.WriteLine(c.State); // Tx
c.Release(50); c.Grant(e,60);
Console.WriteLine($"{c.State}/{c.Ptt}"); // Idle/False
